/* js/core/dom.js */
'use strict';
/* Tiny DOM helpers shared by every UI module. */
const $ = id => document.getElementById(id);
/** Create an element with an optional class and text content. */
function el(tag, cls, txt) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (txt != null) e.textContent = txt;
  return e;
}
/** Restart a one-shot CSS animation class on an element (default: 'pop'). */
const pop = (e, c) => {
  if (!e) return;
  c = c || 'pop';
  e.classList.remove(c);
  void e.offsetWidth;
  e.classList.add(c);
};
/** Row of level pips (filled up to l, out of max). */
function pips(l, max) {
  const d = el('div', 'pips');
  for (let i = 0; i < max; i++) d.appendChild(el('i', i < l ? 'on' : ''));
  return d;
}

/* iPhone Safari ignores user-scalable=no: a quick second tap in the same spot still zooms in, and two fingers pinch.
   Swallow the second of two quick taps close together (not in text fields), and the pinch gestures. */
(() => {
  let lastT = 0,
    lastX = 0,
    lastY = 0;
  document.addEventListener(
    'touchend',
    e => {
      const t = e.changedTouches[0],
        now = performance.now();
      if (!t) return;
      const near = Math.hypot(t.clientX - lastX, t.clientY - lastY) < 60;
      if (now - lastT < 350 && near && !/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)) e.preventDefault();
      lastT = now;
      lastX = t.clientX;
      lastY = t.clientY;
    },
    { passive: false }
  );
  for (const g of ['gesturestart', 'gesturechange', 'gestureend'])
    document.addEventListener(g, e => e.preventDefault(), { passive: false });
})();

;


/* js/core/clipboard.js */
'use strict';
/* Shared clipboard operation. UI callers own their messages; the fallback never depends on hidden screens. */
async function copyToClipboard(text) {
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(String(text));
      return true;
    }
  } catch {
    // Clipboard permissions or browser support can fail; try a temporary focusable field.
  }
  let field, previous;
  try {
    previous = document.activeElement;
    field = document.createElement('textarea');
    field.value = String(text);
    field.readOnly = true;
    field.setAttribute('aria-hidden', 'true');
    field.style.cssText = 'position:fixed;top:0;left:-9999px;width:1px;height:1px;opacity:0;pointer-events:none;';
    document.body.appendChild(field);
    field.focus({ preventScroll: true });
    field.select();
    field.setSelectionRange(0, field.value.length);
    return !!document.execCommand('copy');
  } catch {
    return false;
  } finally {
    if (field) field.remove();
    try {
      if (previous && previous.focus) previous.focus({ preventScroll: true });
    } catch {}
  }
}

;


/* js/core/codes.js */
'use strict';
/* Signed, copy-pasteable codes (score shares, gift codes): PREFIX-<base64url(field|field|…|signature)>.
   The signature only stops casual editing; the salt is visible in the page source. */
/** FNV-1a hash as a short base-36 string. */
const sig = s => {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(36);
};
/** UTF-8 safe, URL-safe base64 without padding. */
const b64 = s =>
  btoa(unescape(encodeURIComponent(s)))
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
const unb64 = s => decodeURIComponent(escape(atob(s.replace(/-/g, '+').replace(/_/g, '/'))));
/** Build a signed code from fields (fields must not contain '|'). */
function packCode(prefix, fields, salt) {
  const body = fields.join('|');
  return prefix + '-' + b64(body + '|' + sig(body + salt));
}
/** Find a code with this prefix anywhere in txt; returns its n fields (strings), or null if missing or tampered. */
function unpackCode(prefix, txt, n, salt) {
  const m = new RegExp(prefix + '-([A-Za-z0-9_-]+)').exec(txt || '');
  if (!m) return null;
  try {
    const p = unb64(m[1]).split('|');
    if (p.length !== n + 1) return null;
    const f = p.slice(0, n);
    return sig(f.join('|') + salt) === p[n] ? f : null;
  } catch {
    return null;
  }
}

;


/* js/core/save.js */
'use strict';
/* Persistent profile (coins, unlocks, settings, stats) in localStorage. */
const SAVE_KEY = 'ashen_arena_modular_test_v1';
const defSave = () => ({
  ver: 2,
  coins: 0,
  sp: 0,
  name: '',
  board: [],
  perm: {},
  chars: { knight: 1 },
  weps: { sword: 1, pistol: 1 },
  char: 'knight',
  tree: {},
  penalties: {},
  ach: {},
  /** ids of gift codes already redeemed on this device */
  gifts: {},
  /** today's missions and progress (js/game/daily.js) */
  daily: null,
  stats: {
    kills: 0,
    runs: 0,
    bestTime: 0,
    bestLvl: 0,
    bosses: 0,
    maxBoss: 0,
    legend: 0,
    abyss: 0,
    evos: 0,
    /** fastest boss kill in one run (seconds), 0 = none yet */
    ft: 0,
    /** weekly counters: wk is the ISO week they belong to, reset by weeklyRoll */
    wk: '',
    wb: 0,
    wkk: 0,
    wt: 0,
    wft: 0,
  },
  set: { sfx: 0.7, mus: 0.5, shadow: 1, shake: 1, qual: 1, left: 1 },
});
let S = defSave();
try {
  const raw = localStorage.getItem(SAVE_KEY);
  if (raw) {
    const o = JSON.parse(raw),
      d = defSave();
    S = Object.assign(d, o);
    if (!(o.ver >= 2)) {
      S.perm = {};
      S.ver = 2;
      S._mig = 1;
    }
    S.stats = Object.assign(defSave().stats, o.stats || {});
    S.set = Object.assign(defSave().set, o.set || {});
  }
} catch {}
function save() {
  try {
    localStorage.setItem(SAVE_KEY, JSON.stringify(S));
  } catch {}
}

;


/* js/core/penalties.js */
'use strict';
/* Owner-issued, one-time corrections, bound to device IDs rather than display names.
   These are local save migrations, not an anti-tamper boundary. Server guards reject old uploads. */
const PLAYER_PENALTY_ID = '2026-11-17-fair-play';
let playerPenaltyDecision = null;
let playerPenaltyReady = false;
function playerPenalty(profile) {
  return playerPenaltyDecision && playerPenaltyDecision.pid === profile.pid ? playerPenaltyDecision : null;
}
/** Fetch only this device's decision; identities and the administrative ledger stay on the server. */
async function refreshPlayerPenalty() {
  playerPenaltyReady = false;
  $('mPlay').disabled = $('mResume').disabled = true;
  playerPenaltyDecision = null;
  const pid = S.pid;
  try {
    if (!pid || !S.pkey) return null;
    const decision = await api('/rest/v1/rpc/get_player_penalty', {
      method: 'POST',
      body: JSON.stringify({ p_pid: pid, p_key: S.pkey }),
      signal: AbortSignal.timeout(4000),
    });
    if (pid !== S.pid) return null;
    if (decision && decision.id === PLAYER_PENALTY_ID)
      playerPenaltyDecision = { ...decision, pid };
    return enforcePlayerPenalty();
  } catch {
    // Offline play stays available; server guards continue rejecting uncorrected uploads.
    return null;
  } finally {
    playerPenaltyReady = true;
    $('mPlay').disabled = $('mResume').disabled = false;
  }
}
function playerPenaltyReceipt(profile) {
  return playerPenalty(profile) && profile.penalties && profile.penalties[PLAYER_PENALTY_ID]
    ? PLAYER_PENALTY_ID
    : '';
}
function applyPlayerPenalty(profile) {
  const penalty = playerPenalty(profile);
  const previous = profile.penalties && profile.penalties[PLAYER_PENALTY_ID];
  if (!penalty || (previous && Number.isInteger(previous.heroesRemoved))) return null;
  const tree = profile.tree || (profile.tree = {}),
    perm = profile.perm || (profile.perm = {}),
    stats = profile.stats || (profile.stats = {}),
    chars = profile.chars || (profile.chars = {});
  let skillsRemoved = 0,
    shopLevelsRemoved = 0,
    heroesRemoved = 0;
  if (!previous) {
    // Remove the deepest unlocked nodes first, keeping the remaining prerequisites intact.
    const nodes = TREE.flatMap((branch, branchIndex) =>
      branch.nodes.map((node, depth) => ({ id: node.id, depth, branchIndex }))
    ).sort((a, b) => b.depth - a.depth || a.branchIndex - b.branchIndex);
    for (const node of nodes) {
      if (skillsRemoved === 4) break;
      if (!tree[node.id]) continue;
      delete tree[node.id];
      skillsRemoved++;
    }
    // Purchase history isn't stored; remove four ranks from the highest shop upgrades.
    for (let i = 0; i < 4; i++) {
      const id = Object.keys(PERM)
        .filter(k => Number.isFinite(perm[k]) && perm[k] > 0)
        .sort((a, b) => perm[b] - perm[a])[0];
      if (!id) break;
      if (--perm[id] <= 0) delete perm[id];
      shopLevelsRemoved++;
    }
    profile.coins = 0;
    for (const key of ['kills', 'bosses', 'bestTime', 'maxBoss', 'abyss', 'ft', 'wb', 'wkk', 'wt', 'wft']) stats[key] = 0;
    profile.board = (profile.board || []).filter(row => row.n !== profile.name);
  }
  // The starter stays playable; withdraw the three most expensive owned heroes.
  const heroes = Object.keys(CHARS)
    .filter(id => id !== 'knight' && chars[id])
    .sort((a, b) => CHARS[b].cost - CHARS[a].cost);
  for (const id of heroes.slice(0, 3)) {
    delete chars[id];
    heroesRemoved++;
  }
  if (!chars[profile.char]) {
    chars.knight = 1;
    profile.char = 'knight';
  }
  profile.penalties = Object.assign({}, profile.penalties, {
    [PLAYER_PENALTY_ID]: {
      skillsRemoved: previous ? previous.skillsRemoved : skillsRemoved,
      shopLevelsRemoved: previous ? previous.shopLevelsRemoved : shopLevelsRemoved,
      heroesRemoved,
    },
  });
  return profile.penalties[PLAYER_PENALTY_ID];
}
function enforcePlayerPenalty() {
  const applied = applyPlayerPenalty(S);
  if (applied) {
    clearRun(); // A pre-correction checkpoint must not re-submit the deleted results.
    save();
  }
  return applied;
}

;


