    r: 2.1,
    spd: [3.3, 3, 4.2, 2.6, 3.2, 3.6][k],
    dmg: (20 + si * 5) * 1.2 * (1 + G.cycle * 0.8) * bossEase(si),
    xp: 120,
    scale: [2.6, 2.3, 2.2, 2.5, 2.4, 2.7][k],
    a1: 3,
    a2: 6,
    a3: 9,
    a4: 2,
    ult: 16,
    ultT: 0,
    leaps: 0,
    spiral: 0,
    spAcc: 0,
    spA: 0,
    burst: 0,
    lx: 0,
    lz: 0,
    y: 0,
