      e0 = spawnAround(t, false); // the ones with special abilities come only every two waves (above)
    if (t === 'wolf') spawnPack('wolf', 2, e0.x, e0.z, 2);
    if (t === 'runner' && Math.random() < 0.5) spawnPack('runner', 1, e0.x, e0.z, 2);
