/* js/ui/chat.js */
'use strict';
/* Public chat: one shared room for everyone playing, stored on the same Supabase project as the leaderboard.
   Messages are read straight from the `chat` table and sent through the `send_chat` RPC (rate limited on the server). */
const CHAT = {
  sel: new Set(), // developer: messages picked for deletion
  pick: false,
  rows: [],
  lastId: 0,
  seenId: +localStorage.getItem('ashen_chat_seen') || 0,
  timer: 0,
  from: 'menu',
  ok: null,
};
/** Fetch the latest messages (newest 60). */
async function chatLoad() {
  try {
    chatMyHash();
    // owner_hash: whose device sent it (to offer 🗑 on your own). A server without it yet: the old columns.
    const cols = 'id,name,msg,created_at' + (CHAT.noOwner ? '' : ',owner_hash');
    const rows = await api('/rest/v1/chat?select=' + cols + '&order=id.desc&limit=60').catch(e => {
      if (CHAT.noOwner || !String(e.message).includes('400')) throw e;
      CHAT.noOwner = true;
      return api('/rest/v1/chat?select=id,name,msg,created_at&order=id.desc&limit=60');
    });
    CHAT.rows = rows.reverse();
    CHAT.ok = true;
  } catch (err) {
    CHAT.ok = false;
  }
  const last = CHAT.rows.length ? CHAT.rows[CHAT.rows.length - 1].id : 0;
  const fresh = last !== CHAT.lastId;
  CHAT.lastId = last;
  if (!$('chat').hidden) {
    chatSeen();
    if (fresh || !$('chatList').childElementCount) chatDraw();
  }
  chatBadge();
}
/** This device's mark on its messages: the same hash the server keeps (sha256 of '#ashen-chat' + the device key). */
async function chatMyHash() {
  const k = profileKey();
  if (CHAT.hashKey === k || CHAT.hashing || !(window.crypto && crypto.subtle)) return;
  CHAT.hashing = true;
  try {
    const b = await crypto.subtle.digest('SHA-256', new TextEncoder().encode('#ashen-chat' + k));
    CHAT.hashKey = k;
    CHAT.myHash = [...new Uint8Array(b)].map(x => x.toString(16).padStart(2, '0')).join('');
    if (!$('chat').hidden) chatDraw();
  } catch (e) {}
  CHAT.hashing = false;
}
/** 🗑 on your own message: a first tap arms it, a second (within 3 s) deletes it. */
function chatDelBtn(r) {
  const b = el('button', 'cDel', '🗑');
  b.setAttribute('aria-label', 'احذف رسالتك');
  b.onclick = async e => {
    e.stopPropagation();
    if (!b.classList.contains('arm')) {
      b.classList.add('arm');
      b.textContent = 'احذف؟';
      setTimeout(() => {
        b.classList.remove('arm');
        b.textContent = '🗑';
      }, 3000);
      return;
    }
    b.disabled = true;
    try {
      const n = await api('/rest/v1/rpc/delete_my_chat', {
        method: 'POST',
        body: JSON.stringify({ p_id: r.id, p_key: profileKey() }),
      });
      if (!n) throw new Error('none');
      CHAT.rows = CHAT.rows.filter(x => x.id !== r.id);
      AU.play('select');
      chatDraw();
    } catch (err) {
      b.disabled = false;
      toast('ما انحذفت، تأكد من الإنترنت');
    }
  };
  return b;
}
function chatSeen() {
  CHAT.seenId = CHAT.lastId;
  try {
    localStorage.setItem('ashen_chat_seen', CHAT.seenId);
  } catch (err) {}
}
function chatBadge() {
  const n = CHAT.rows.filter(r => r.id > CHAT.seenId && r.name !== S.name).length,
    b = $('chatBadge');
  b.hidden = !n;
  b.textContent = n > 9 ? '9+' : n;
}
/** "قبل 3 د" style relative time. */
function chatAgo(ts) {
  const s = Math.max(0, (Date.now() - Date.parse(ts)) / 1000);
  if (s < 60) return 'الآن';
  if (s < 3600) return 'قبل ' + Math.floor(s / 60) + ' د';
  if (s < 86400) return 'قبل ' + Math.floor(s / 3600) + ' س';
  return 'قبل ' + Math.floor(s / 86400) + ' يوم';
}
function chatDraw() {
  const L = $('chatList'),
    atEnd = L.scrollHeight - L.scrollTop - L.clientHeight < 40;
  L.innerHTML = '';
  $('cName').textContent = '✏️ ' + (S.name || 'اسمك');
  const recent = new Set(CHAT.rows.filter(r => Date.now() - Date.parse(r.created_at) < 600000).map(r => r.name));
  $('chatInfo').textContent =
    CHAT.ok === false
      ? '⚠️ الشات غير متاح الحين، تأكد من الإنترنت.'
      : '🌐 غرفة واحدة لكل اللاعبين' + (recent.size ? ' · نشطين آخر 10 دقائق: ' + recent.size : '');
  if (CHAT.ok && !CHAT.rows.length) L.appendChild(el('p', 'note', 'ما فيه رسائل للحين. كن أول من يكتب!'));
  for (const id of CHAT.sel) if (!CHAT.rows.some(r => r.id === id)) CHAT.sel.delete(id);
  chatModBar();
  for (const r of CHAT.rows) {
    const m = el('div', 'cm' + (r.name === S.name ? ' me' : '') + (CHAT.sel.has(r.id) ? ' sel' : ''));
    if (CHAT.pick)
      m.onclick = () => {
        CHAT.sel.has(r.id) ? CHAT.sel.delete(r.id) : CHAT.sel.add(r.id);
        m.classList.toggle('sel', CHAT.sel.has(r.id));
        chatModBar();
      };
    const body = el('div', 'cmB');
    body.append(profileLink(el('b', '', r.name), r.name), el('small', '', chatAgo(r.created_at)));
    if (r.owner_hash && CHAT.myHash && r.owner_hash === CHAT.myHash && !CHAT.pick) body.appendChild(chatDelBtn(r));
    body.appendChild(el('p', '', r.msg));
    m.append(avatarEl(r.name), body);
    L.appendChild(m);
  }
  avatarFetch(CHAT.rows.map(r => r.name)); // pictures we don't have yet (the chat redraws when they come)
  if (atEnd || L.dataset.first !== '1') {
    L.scrollTop = L.scrollHeight;
    L.dataset.first = '1';
  }
}
/** Open the chat (from the menu or the pause screen) and poll every 4 s while it is open. */
function openChat(from) {
  CHAT.from = from;
  $('chatList').dataset.first = '';
  if (from === 'pause') {
    show('pause', false);
    show('chat', true);
  } else go('chat');
  chatDraw();
  chatLoad();
  clearInterval(CHAT.timer);
  CHAT.timer = setInterval(chatLoad, 4000);
  if (!S.name) askName();
}
function closeChat() {
  clearInterval(CHAT.timer);
  CHAT.timer = setInterval(chatLoad, 30000);
  if (CHAT.from === 'pause') {
    show('chat', false);
    show('pause', true);
  } else go('menu');
}
let chatBusy = false;
async function chatSend() {
  const inp = $('chatIn'),
    msg = inp.value.trim();
  if (!msg || chatBusy) return; // one send at a time: no double posts from a double tap
  if (!S.name) {
    askName();
    return;
  }
  chatBusy = true;
  inp.value = ''; // clear right away; put it back only if sending fails
  $('chatSend').disabled = true;
  try {
    // signed with this device's key (so you can delete it later); a server without that yet: the old way
    const send = b => api('/rest/v1/rpc/send_chat', { method: 'POST', body: JSON.stringify(b) });
    await send({ p_name: S.name, p_msg: msg, p_key: profileKey() }).catch(e => {
      if (!String(e.message).includes('404')) throw e;
      return send({ p_name: S.name, p_msg: msg });
    });
    AU.play('select');
  } catch (err) {
    if (!inp.value) inp.value = msg;
    toast(String(err.message).includes('400') ? 'لحظة، لا ترسل بسرعة 🙂' : 'ما انرسلت، تأكد من الإنترنت');
  }
  chatBusy = false;
  $('chatSend').disabled = false;
  inp.focus();
  chatLoad();
}
/* ---- developer moderation: pick messages and delete them (the server checks the developer code) */
let wipeAllArm = false;
function chatModBar() {
  const B = $('chatMod');
  B.hidden = !S.dev;
  if (!S.dev) return;
  B.innerHTML = '';
  labBtn(B, CHAT.pick ? '✖️ إلغاء التحديد' : '☑️ حدد رسائل', () => {
    CHAT.pick = !CHAT.pick;
    CHAT.sel.clear();
    chatDraw();
  });
  if (CHAT.pick)
    labBtn(B, '🗑 احذف المحدد (' + CHAT.sel.size + ')', async () => {
      if (!CHAT.sel.size) return toast('اضغط على الرسائل اللي تبي تحذفها أول');
      if (await chatAdminDelete([...CHAT.sel])) {
        CHAT.sel.clear();
        CHAT.pick = false;
      }
    });
  labBtn(B, wipeAllArm ? '⚠️ متأكد؟ اضغط مرة ثانية' : '🧨 احذف الكل', async () => {
    if (!wipeAllArm) {
      wipeAllArm = true;
      chatModBar();
      setTimeout(() => {
        wipeAllArm = false;
        if (!$('chat').hidden) chatModBar();
      }, 3000);
      return;
    }
    wipeAllArm = false;
    await chatAdminDelete(null);
  });
}
/** Delete the given message ids (or all when null). Returns true on success. */
async function chatAdminDelete(ids) {
  let key = S.devKey;
  if (!key) {
    key = (prompt('اكتب كود المطور للتأكيد') || '').toUpperCase().replace(/\s+/g, '');
    if (!key) return false;
  }
  try {
    const n = await api('/rest/v1/rpc/admin_delete_chat', {
      method: 'POST',
      body: JSON.stringify({ p_key: key, p_ids: ids }),
    });
    S.devKey = key;
    save();
    AU.play('select');
    toast('🗑 انحذفت ' + (n | 0) + ' رسالة');
    CHAT.lastId = -1;
    await chatLoad();
    chatDraw();
    return true;
  } catch (err) {
    const m = String(err.message);
    if (m.includes('404')) toast('خاصية الحذف ما انفعّلت في السيرفر للحين (ملف chat-admin.sql)');
    else if (m.includes('400')) {
      delete S.devKey;
      save();
      toast('كود المطور غير صحيح');
    } else toast('ما انحذفت، تأكد من الإنترنت');
    return false;
  }
}
$('mChat').onclick = () => {
  AU.init();
  AU.play('select');
  openChat('menu');
};
$('pChat').onclick = () => openChat('pause');
$('cBack').onclick = closeChat;
$('cName').onclick = askName;
$('chatForm').onsubmit = e => {
  e.preventDefault();
  chatSend();
};
// keys typed in the chat box must not move the hero or trigger shortcuts
$('chatIn').addEventListener('keydown', e => e.stopPropagation());
CHAT.timer = setInterval(chatLoad, 30000);
setTimeout(chatLoad, 1500);

;


/* js/ui/avatar.js */
'use strict';
/* Profile pictures: a player picks a photo from his device; it is cropped to a square, shrunk to a small JPEG and
   stored with his profile (save_avatar RPC, checked against his device key). The chat shows each sender's picture
   (or his hero's portrait, or the first letter of his name, when he has none). */
const AVA = { map: new Map(), busy: false, want: new Set() };
const AVA_SIZE = 160;
/** Crop the file to its centre square, scale it down and encode it (kept under the server's limit). */
function avatarEncode(file) {
  return new Promise((ok, no) => {
    const url = URL.createObjectURL(file),
      img = new Image();
    img.onload = () => {
      URL.revokeObjectURL(url);
      const c = document.createElement('canvas');
      c.width = c.height = AVA_SIZE;
      const x = c.getContext('2d'),
        s = Math.min(img.naturalWidth, img.naturalHeight);
      if (!s) return no(new Error('empty'));
      x.fillStyle = '#1a1626';
      x.fillRect(0, 0, AVA_SIZE, AVA_SIZE);
      x.drawImage(img, (img.naturalWidth - s) / 2, (img.naturalHeight - s) / 2, s, s, 0, 0, AVA_SIZE, AVA_SIZE);
      let q = 0.86,
        d = c.toDataURL('image/jpeg', q);
      while (d.length > 55000 && q > 0.3) d = c.toDataURL('image/jpeg', (q -= 0.12));
      d.length > 58000 ? no(new Error('big')) : ok(d);
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      no(new Error('not an image'));
    };
    img.src = url;
  });
}
/** Save (or, with null, remove) this player's picture on the server. */
async function avatarSave(data) {
  if (!S.name) return (askName(), false);
  try {
    await api('/rest/v1/rpc/save_avatar', {
      method: 'POST',
      body: JSON.stringify({ p_pid: myPid(), p_key: profileKey(), p_name: S.name, p_img: data }),
    });
  } catch (e) {
    const m = String(e.message);
    toast(m.includes('400') ? 'لحظة شوي وجرّب مرة ثانية' : 'ما انرفعت الصورة، تأكد من الإنترنت');
    return false;
  }
  S.avatar = data || '';
  save();
  AVA.map.set(S.name, { img: S.avatar, ch: S.char, t: Date.now() });
  AU.play('select');
  toast(data ? '📷 تم تحديث صورتك' : '🗑 انحذفت صورتك');
  avatarRefresh();
  return true;
}
// The 📷 button in your own card picks a photo and uploads it. The file input lives in the page for good and the 📷 button is a <label> for it: iPhone Safari drops a picker
// made on the fly (its choice never arrives), and a label is the one way every browser opens the photo picker.
$('avaFile').onchange = async () => {
  const inp = $('avaFile'),
    f = inp.files && inp.files[0];
  inp.value = ''; // the same photo can be picked again
  if (!f) return;
  let d;
  try {
    d = await avatarEncode(f);
  } catch (e) {
    return toast('ما قدرت أقرأ الصورة، جرّب صورة ثانية');
  }
  $('pcPic').style.backgroundImage = 'url(' + d + ')';
  if (await avatarSave(d)) profileOpen(S.name);
};
/** What to show for a player: his photo, else his hero, else nothing (the caller draws his initial). */
function avatarOf(name) {
  if (name === S.name && S.avatar) return S.avatar;
  const a = AVA.map.get(name);
  if (a && a.img) return a.img;
  const ch = name === S.name ? S.char : a && a.ch;
  // a hero portrait is drawn with the game's renderer (it rebuilds the hero for a moment): only on the menu;
  // during a run or a duel only one already drawn is used
  if (!ch || !CHARS[ch]) return '';
  return (G.state === 'menu' ? heroPortrait(ch) : PORTRAITS[ch]) || '';
}
/** The round picture beside a chat message. */
function avatarEl(name) {
  const d = el('i', 'cav');
  d.dataset.n = name;
  avatarPaint(d);
  return profileLink(d, name);
}
function avatarPaint(d) {
  const src = avatarOf(d.dataset.n),
    bg = src ? 'url("' + src + '")' : '';
  if (d.dataset.src === src) return;
  d.dataset.src = src;
  d.style.backgroundImage = bg;
  d.textContent = src ? '' : [...String(d.dataset.n || '?')][0];
}
/** Pictures that just arrived: put them on the messages already shown. */
function avatarRefresh() {
  for (const d of document.querySelectorAll('.cav')) avatarPaint(d);
}
/** Fetch the pictures of these players (those not known, or known for over 2 minutes); redraw the chat after. */
async function avatarFetch(names) {
  const now = Date.now();
  for (const n of names) {
    const a = AVA.map.get(n);
    if (n && (!a || now - a.t > 120000)) AVA.want.add(n);
  }
  if (AVA.busy || !AVA.want.size || (typeof NET_LOCAL !== 'undefined' && NET_LOCAL)) return;
  AVA.busy = true;
  const list = [...AVA.want].slice(0, 40);
  list.forEach(n => AVA.want.delete(n));
  const q = list.map(n => '"' + n.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"').join(',');
  let changed = false;
  try {
    const rows = await api(
      '/rest/v1/profiles?select=name,avatar,stats&name=in.(' + encodeURIComponent(q) + ')&order=updated_at.desc'
    );
    const got = new Map();
    // the newest profile of each name; a picture from any of them if the newest has none
    for (const r of rows || []) {
      const g = got.get(r.name) || { img: '', ch: r.stats && r.stats.ch };
      if (!g.img && r.avatar) g.img = r.avatar;
      got.set(r.name, g);
    }
    for (const n of list) {
      const g = got.get(n) || { img: '', ch: '' },
        old = AVA.map.get(n);
      if (!old || old.img !== g.img || old.ch !== g.ch) changed = true;
      AVA.map.set(n, { img: g.img, ch: g.ch, t: now });
    }
  } catch (e) {
    for (const n of list) if (!AVA.map.has(n)) AVA.map.set(n, { img: '', ch: '', t: now - 90000 });
  }
  AVA.busy = false;
  if (changed) avatarRefresh();
  if (AVA.want.size) avatarFetch([]);
}

;


/* js/ui/profile.js */
'use strict';
/* Player profiles: each device uploads a small public card of its progress (Supabase `profiles`, updated through
   the save_profile RPC with a device key only that device knows). Tapping a player's name anywhere opens the card. */
function profileKey() {
  if (!S.pkey) {
    const a = new Uint8Array(16);
    (window.crypto || {}).getRandomValues
      ? crypto.getRandomValues(a)
      : a.forEach((_, i) => (a[i] = Math.random() * 256));
    S.pkey = [...a].map(b => b.toString(16).padStart(2, '0')).join('');
    save();
  }
  return S.pkey;
}
/** The public part of this player's progress. */
function profileStats() {
  const st = S.stats;
  return {
    lvl: st.bestLvl | 0,
    t: Math.round(st.bestTime || 0),
    b: st.bosses | 0,
    ft: Math.round(st.ft || 0),
    wk: st.wk || '',
    wb: st.wb | 0,
    wkk: st.wkk | 0,
    wt: Math.round(st.wt || 0),
    wft: Math.round(st.wft || 0),
    mb: st.maxBoss | 0,
    ab: st.abyss | 0,
    k: st.kills | 0,
    r: st.runs | 0,
    lg: st.legend | 0,
    ev: st.evos | 0,
    h: Object.keys(S.chars || {}).length,
    ach: Object.keys(S.ach || {}).length,
    tr: Object.keys(S.tree || {}).length,
    ch: S.char,
    penalty: playerPenaltyReceipt(S),
  };
}
let profileBusy = false;
async function profileSync() {
  if (!playerPenaltyReady || !S.name || profileBusy || (typeof NET_LOCAL !== 'undefined' && NET_LOCAL)) return;
  profileBusy = true;
  try {
    await api('/rest/v1/rpc/save_profile', {
      method: 'POST',
      body: JSON.stringify({ p_pid: myPid(), p_key: profileKey(), p_name: S.name, p_stats: profileStats() }),
    });
  } catch (e) {}
  profileBusy = false;
}
/** How far a player got, in words. */
function profileReach(s) {
  if ((s.mb | 0) >= STAGES.length - 1) return 'أنهى المراحل السبع' + (s.ab ? '، ونزل الهاوية ' + s.ab + ' مرة' : '');
  const i = Math.min(STAGES.length - 2, s.mb | 0);
  return 'وصل المرحلة ' + (i + 1) + ': ' + STAGES[i].n;
}
/** Open the card of the player called `name` (the newest profile with that name). */
async function profileOpen(name) {
  if (!name) return;
  AU.play('select');
  const box = $('pcard');
  box.hidden = false;
  $('pcName').textContent = name;
  $('pcBody').innerHTML = '';
  $('pcBody').appendChild(el('p', 'note', '…'));
  $('pcPic').style.backgroundImage = '';
  let prof = null,
    duels = [],
    score = null;
  const mine = name === S.name;
  try {
    const q = encodeURIComponent(name);
    const [p, d, sc] = await Promise.all([
      mine
        ? null
        : api(
            '/rest/v1/profiles?select=name,stats,updated_at,avatar&name=eq.' + q + '&order=updated_at.desc&limit=1'
          ).catch(() => []),
      api('/rest/v1/duels?select=a,b,winner&or=(a.eq.' + q + ',b.eq.' + q + ')&limit=500').catch(() => []),
      api('/rest/v1/scores?select=kills,lvl,t,bosses&name=eq.' + q + '&limit=1').catch(() => []),
      onlineRows ? null : loadOnline(), // for his place on the leaderboard
    ]);
    prof = mine ? { name, stats: profileStats(), updated_at: new Date().toISOString() } : p && p[0];
    duels = d || [];
    score = sc && sc[0];
  } catch (e) {}
  if (box.hidden || $('pcName').textContent !== name) return; // closed or switched meanwhile
  const B = $('pcBody');
  B.innerHTML = '';
  if (!prof && !score && !duels.length) {
    B.appendChild(el('p', 'note', 'ما عنده ملف للحين. يطلع ملفه بعد ما يلعب جولة بالتحديث الجديد.'));
    return;
  }
  const s = (prof && prof.stats) || {};
  // the player's own photo; else his hero's portrait
  const photo = mine ? S.avatar : prof && prof.avatar;
  if (photo) $('pcPic').style.backgroundImage = 'url(' + photo + ')';
  if (prof && !mine) AVA.map.set(name, { img: photo || '', ch: s.ch, t: Date.now() });
  if (mine) {
    // your card: change or remove your picture
    const row = el('div', 'pcAva');
    const up = el('label', 'btn sm go', photo ? '📷 غيّر صورتك' : '📷 حط صورتك');
    up.htmlFor = 'avaFile';
    row.appendChild(up);
    if (photo) {
      const rm = el('button', 'btn sm', '🗑 احذفها');
      rm.onclick = async () => (await avatarSave(null)) && profileOpen(S.name);
      row.appendChild(rm);
    }
    B.appendChild(row);
  }
  if (s.ch && CHARS[s.ch]) {
    const img = photo ? '' : heroPortrait(s.ch);
    if (img) $('pcPic').style.backgroundImage = 'url(' + img + ')';
    $('pcHero').textContent = CHARS[s.ch].i + ' ' + CHARS[s.ch].n;
  } else $('pcHero').textContent = '';
  const row = (icon, label, val) => {
    const r = el('div', 'pcRow');
    r.append(el('span', '', icon + ' ' + label), el('b', '', val));
    B.appendChild(r);
  };
  if (prof) {
    B.appendChild(el('p', 'pcReach', '🗺️ ' + profileReach(s)));
    // the same numbers the leaderboard ranks by, and his place on it
    const pl = onlineOK && onlineRows ? onlineRows.findIndex(e => e.n === name) : -1;
    if (pl >= 0) row('🏆', 'ترتيبه بالصدارة', '#' + (pl + 1));
    row('👑', 'مجموع الزعماء', s.b || 0);
    row('💀', 'مجموع القتلات', (s.k || 0).toLocaleString('en'));
    row('🎮', 'جولات لعبها', s.r || 0);
    row('⭐', 'أعلى مستوى', s.lvl || 0);
    row('⏱', 'أطول جولة', fmtT(s.t || 0));
    row('🦸', 'أبطال مفتوحة', (s.h || 1) + ' / ' + Object.keys(CHARS).length);
    row('🏆', 'إنجازات', (s.ach || 0) + ' / ' + ACH.length);
  }
  if (!prof && score) {
    // no profile yet (hasn't played since profiles arrived): build the card from the leaderboard record
    B.appendChild(el('p', 'pcReach', '🗺️ ' + profileReach({ mb: score.bosses })));
    row('💀', 'أحسن جولة', score.kills + ' قتلة');
    row('⭐', 'أعلى مستوى', score.lvl);
    row('⏱', 'أطول جولة', fmtT(score.t || 0));
    row('👑', 'زعماء في جولة وحدة', score.bosses || 0);
  }
  if (duels.length) {
    const w = duels.filter(r => r.winner === name).length;
    row('⚔️', 'المبارزات', w + ' فوز · ' + (duels.length - w) + ' خسارة');
  }
  if (prof && !mine) B.appendChild(el('p', 'note pcSeen', 'آخر ظهور ' + chatAgo(prof.updated_at)));
  if (!prof)
    B.appendChild(
      el('p', 'note pcSeen', 'باقي معلوماته (الأبطال، الإنجازات، مجموع القتلات) تطلع بعد ما يلعب بالتحديث الجديد.')
    );
}
$('pcClose').onclick = () => ($('pcard').hidden = true);
$('pcard').onclick = e => {
  if (e.target.id === 'pcard') $('pcard').hidden = true;
};
/** Make an element (holding a player's name) open that player's card. */
function profileLink(elm, name) {
  elm.classList.add('pname');
  elm.onclick = e => {
    e.stopPropagation();
    profileOpen(name);
  };
  return elm;
}
$('mProfile').onclick = () => (S.name ? profileOpen(S.name) : askName());
setTimeout(profileSync, 4000);

