          s.x,
          s.y,
          s.z,
          s.t * 8,
          0.22,
          0.48,
          0.22,
          s.evo ? 1 : 0.35,
          s.evo ? 0.25 : 0.85,
          s.evo ? 0.15 : 0.4,
          s.t * 6
