      const k = q.l / q.d;
      m.position.set(q.x, 0.1, q.z);
      m.scale.set(q.r, q.r, 1);
      const zc = q.f ? 0xffa020 : q.sty ? BOSS_ULTS[q.sty - 1].zone : 0xff2a1a;
      m.material.color.setHex(zc);
