      o.frequency.exponentialRampToValueAtTime(38, t + at + 0.5);
      g.gain.setValueAtTime(0.0001, t + at);
      g.gain.exponentialRampToValueAtTime(big ? 1 : 0.8, t + at + 0.01);
      g.gain.exponentialRampToValueAtTime(0.0001, t + at + 0.9);
      o.connect(g);
      g.connect(AU.sg);
