      g.gain.exponentialRampToValueAtTime(v, t + at + 0.015);
      g.gain.exponentialRampToValueAtTime(0.0001, t + at + dur);
      o.connect(g);
      g.connect(AU.sg);
      o.start(t + at);
      o.stop(t + at + dur + 0.05);
