          gV.x + rand(-0.1, 0.1),
          gV.y,
          gV.z + rand(-0.1, 0.1),
          rand(-0.2, 0.2),
          -0.3,
          rand(-0.2, 0.2),
          0.007 + Math.random() * 0.008
