  sg.setAttribute('position', new THREE.BufferAttribute(p, 3));
  const stars = new THREE.Points(
    sg,
    new THREE.PointsMaterial({
      color: 0xd8dcff,
      size: 1.6,
      sizeAttenuation: false,
      fog: false,
      transparent: true,
      opacity: 0.8,
    })
  );
