  if (F) {
    if (F.hit < 0) F.v.pooled = 0; // (otherwise its pool already spread)
    if (F.k.act !== 'dead') {
      F.k.start('idle');
      F.k.play('idle', 0.3);
    }
  }
  $('duel').classList.remove('cine');
  document.documentElement.classList.remove('cine');
  if ($('dMsg').querySelector('b').textContent) pop($('dMsg'), 'show');
